const APP_DATA=window.APP_DATA;
const PASS='hoahikari1991';
let unlocked=false;
let state={page:'home',exam:null,mode:null,index:0,answers:{},showSolution:false,selectedQuestions:[],filterSubject:null,filterPart:null,timer:null,remaining:0,historyId:null};
const root=document.getElementById('app');
const subjects=APP_DATA.meta.subjects;
const examKey=y=>typeof y==='number'?`第${y}回`:y;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function nav(p,label){return `<button class="${state.page===p?'active':''}" onclick="go('${p}')">${label}</button>`}
function go(p){if(state.timer){clearInterval(state.timer);state.timer=null}state.page=p;if(p!=='exam'){state.exam=null;state.selectedQuestions=[];state.filterSubject=null;state.filterPart=null}render()}
function unlock(){const v=(document.getElementById('pw')?.value||'').trim();if(v===PASS){unlocked=true;render()}else{const e=document.getElementById('err');if(e)e.textContent='Mật khẩu chưa đúng.'}}
function lock(){unlocked=false;render()}
function home(){return `<section class="hero"><h1>🌸 HOAHIKARI</h1><p>LUYỆN ĐỀ THI CCQG KAIGO</p><p style="margin-top:12px">Chọn đề → 🎯 CHẾ ĐỘ THI hoặc 📚 CHẾ ĐỘ HỌC.</p></section><div class="grid">${APP_DATA.meta.exams.map(y=>{const e=examKey(y);return `<div class="card"><span class="tag">125 câu</span><h2>${e}</h2><p class="small">Giữ nguyên thứ tự câu 1 → 125 của đúng kỳ thi.</p><div class="exam-actions"><button class="btn primary" onclick="choose('${e}','test')">🎯 CHẾ ĐỘ THI</button><button class="btn pink" onclick="choose('${e}','learn')">📚 CHẾ ĐỘ HỌC</button></div><button class="btn secondary" style="width:100%;margin-top:8px" onclick="chooseSubjectMenu('${e}')">📖 LÀM THEO MÔN</button></div>`}).join('')}</div>`}
function choose(e,m){state.exam=e;state.mode=m;state.index=0;state.answers={};state.showSolution=false;state.selectedQuestions=APP_DATA.exams[e].map(q=>q.n);state.filterSubject=null;state.filterPart=null;startTimer();state.page='exam';render()}
function chooseSubjectMenu(e){state.exam=e;state.page='subjectMenu';render()}
function subjectMenu(){const e=state.exam;return `<section class="hero"><h1>📖 ${e} — LÀM THEO MÔN</h1><p>Chọn 1 trong 13 môn của chính đề ${e}. Thứ tự môn giữ nguyên theo cấu trúc.</p></section><div class="grid">${subjects.map((x,i)=>{const [p,s]=x;const qs=APP_DATA.exams[e].filter(q=>q.subject===s);return `<div class="card"><span class="tag">${i+1}. PHẦN ${p}</span><h3>${esc(s)}</h3><p class="small">${qs.length} câu trong ${e}</p><div class="exam-actions"><button class="btn primary" onclick="startSubject('${e}','${encodeURIComponent(p)}','${encodeURIComponent(s)}','test')">🎯 LÀM ĐỀ</button><button class="btn pink" onclick="startSubject('${e}','${encodeURIComponent(p)}','${encodeURIComponent(s)}','learn')">📚 HỌC</button></div></div>`}).join('')}</div>`}
function startSubject(e,p,s,m){p=decodeURIComponent(p);s=decodeURIComponent(s);const arr=APP_DATA.exams[e].filter(q=>q.subject===s&&q.part===p);if(!arr.length){alert('Môn này chưa có dữ liệu.');return}state.exam=e;state.mode=m;state.filterSubject=s;state.filterPart=p;state.selectedQuestions=arr.map(q=>q.n);state.index=0;state.answers={};state.showSolution=false;startTimer();state.page='exam';render()}
function currentQs(){const all=APP_DATA.exams[state.exam]||[];const wanted=new Set(state.selectedQuestions);return all.filter(q=>wanted.has(q.n)).sort((a,b)=>a.n-b.n)}
function startTimer(){if(state.timer)clearInterval(state.timer);const n=currentQs().length||125;state.remaining=state.mode==='test'?(state.filterPart==='A'?105:state.filterPart==='BC'?115:220)*60:0;if(state.mode==='test'){state.timer=setInterval(()=>{state.remaining--;if(state.remaining<=0){submitAny(true)}else renderTimer()},1000)}}
function fmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderTimer(){const t=document.getElementById('timer');if(t)t.textContent='⏱️ '+fmt(state.remaining)}
function pick(n,v){state.answers[n]=v;render()}
function prevQ(){if(state.index>0){state.index--;state.showSolution=false;render()}}
function nextQ(){const a=currentQs();if(state.index<a.length-1){state.index++;state.showSolution=false;render()}else submitAny(false)}
function toggleSolution(){state.showSolution=!state.showSolution;render()}
function answerLabel(a){return a&&a.length?a.join('、'):'—'}
function solutionView(q){if(!state.showSolution)return '';let viq=q.viQuestion?`<div class="solutiontext"><b>🇻🇳 DỊCH ĐỀ</b>\n${esc(q.viQuestion)}</div>`:'';let vic=q.viChoices?.length?`<div class="solutiontext"><b>🇻🇳 DỊCH 5 ĐÁP ÁN</b>\n${q.viChoices.map((x,i)=>`${i+1}. ${esc(x)}`).join('\n')}</div>`:'';return `<div class="solutionbox"><div class="answerbox">✅ ĐÁP ÁN CHUẨN: ${answerLabel(q.answer)}</div>${viq}${vic}<h3>📚 LỜI GIẢI SONG NGỮ</h3><div class="solutiontext">${esc(q.solution||'Chưa có lời giải song ngữ trong dữ liệu nguồn.')}</div>${q.keywords?.length?`<div class="solutiontext"><b>🧠 TỪ VỰNG / TỪ KHÓA</b>\n${esc(Array.isArray(q.keywords)?q.keywords.join('\n'):q.keywords)}</div>`:''}${q.tip?`<div class="solutiontext"><b>💡 MẸO</b>\n${esc(q.tip)}</div>`:''}</div>`}
function examPage(){const a=currentQs();if(!a.length)return '<div class="card">Chưa có dữ liệu.</div>';const q=a[state.index],chosen=state.answers[q.n];return `<div class="toolbar"><div><div class="questionNo">${state.exam} • Câu ${q.n} / 125</div><div class="qmeta"><span class="tag">PHẦN ${q.part}</span><span class="tag">${esc(q.subject)}</span></div></div>${state.mode==='test'?'<b id="timer">⏱️ '+fmt(state.remaining)+'</b>':''}</div><div class="progress"><span style="width:${((state.index+1)/a.length)*100}%"></span></div><div class="qcard"><div class="qtext">${esc(q.question)}</div>${q.choices.map((c,i)=>`<button class="choice ${chosen===i+1?'sel':''}" onclick="pick(${q.n},${i+1})"><span class="num">${i+1}</span><span>${esc(c)}</span></button>`).join('')}<div class="actions"><button class="btn secondary" onclick="prevQ()" ${state.index===0?'disabled':''}>← CÂU TRƯỚC</button><button class="btn secondary" onclick="submitAny(false)">🏁 NỘP BÀI</button>${state.mode==='learn'?`<button class="btn pink" onclick="toggleSolution()">${state.showSolution?'🙈 ẨN LỜI GIẢI':'📖 XEM LỜI GIẢI SONG NGỮ'}</button>`:''}<button class="btn primary" onclick="nextQ()">${state.index===a.length-1?'🏁 NỘP BÀI':'➡️ LÀM TIẾP'}</button></div>${solutionView(q)}</div>`}
function saveHistory(){const a=currentQs();const rec={id:Date.now(),date:new Date().toISOString(),exam:state.exam,mode:state.mode,subject:state.filterSubject||null,part:state.filterPart||null,total:a.length,answered:Object.keys(state.answers).length,score:a.reduce((n,q)=>n+((state.answers[q.n]!=null&&q.answer?.includes(state.answers[q.n]))?1:0),0),answers:{...state.answers},questions:a.map(q=>q.n)};let h=[];try{h=JSON.parse(localStorage.getItem('hoahikari_history')||'[]')}catch(e){}h.unshift(rec);h=h.slice(0,100);try{localStorage.setItem('hoahikari_history',JSON.stringify(h))}catch(e){}state.historyId=rec.id;return rec}
function submitAny(auto){const a=currentQs();if(!a.length)return;if(state.timer)clearInterval(state.timer);state.timer=null;saveHistory();state.page='result';render()}
function history(){let h=[];try{h=JSON.parse(localStorage.getItem('hoahikari_history')||'[]')}catch(e){}return `<section class="hero"><h1>🕘 LỊCH SỬ LÀM BÀI</h1><p>Lưu ngày giờ, đề, môn, số câu và kết quả trên thiết bị này.</p></section><div class="card">${h.length?h.map(r=>`<div class="history-item"><div><b>${esc(r.exam)} • ${r.mode==='test'?'🎯 Thi':'📚 Học'}${r.subject?' • '+esc(r.subject):''}</b><div class="small">${new Date(r.date).toLocaleString('vi-VN')} • ${r.answered}/${r.total} câu • Đúng ${r.score}/${r.total}</div></div><button class="btn secondary" onclick="showHistoryResult(${r.id})">XEM KẾT QUẢ</button></div>`).join(''):'<p class="small">Chưa có lịch sử làm bài.</p>'}</div>`}
function showHistoryResult(id){state.historyId=id;state.page='result';render()}
function result(){let h=[];try{h=JSON.parse(localStorage.getItem('hoahikari_history')||'[]')}catch(e){}const r=h.find(x=>x.id===state.historyId)||h[0];if(!r)return '<div class="card">Chưa có kết quả.</div>';const qs=APP_DATA.exams[r.exam]||[];const details=r.questions.map(n=>{const q=qs.find(x=>x.n===n);if(!q)return '';const u=r.answers?.[n];const ok=u!=null&&q.answer?.includes(u);return `<div class="history-q"><b>Câu ${n}</b> <span class="tag ${ok?'oktag':'badt'}">${u==null?'CHƯA TRẢ LỜI':ok?'ĐÚNG':'SAI'}</span><div class="small">Bạn chọn: ${u??'—'} • Đáp án: ${answerLabel(q.answer)}</div></div>`}).join('');return `<section class="hero"><h1>🏁 KẾT QUẢ BÀI LÀM</h1><p>${esc(r.exam)} • ${r.mode==='test'?'🎯 Chế độ thi':'📚 Học'}${r.subject?' • '+esc(r.subject):''}</p></section><div class="grid"><div class="card"><h2>${r.score} / ${r.total}</h2><div class="small">Số câu đúng</div></div><div class="card"><h2>${r.answered} / ${r.total}</h2><div class="small">Đã trả lời</div></div><div class="card"><h2>${r.total?Math.round(r.score/r.total*100):0}%</h2><div class="small">Tỷ lệ đúng</div></div></div><div class="card"><p>🕘 ${new Date(r.date).toLocaleString('vi-VN')}</p><h3>📋 Chi tiết từng câu</h3>${details}</div><button class="btn secondary" onclick="go('history')">← LỊCH SỬ</button>`}
function subjectsPage(){return `<section class="hero"><h1>📖 LUYỆN THEO MÔN</h1><p>Chọn đề trước → chọn 1 trong 13 môn → 🎯 LÀM ĐỀ hoặc 📚 HỌC.</p></section><div class="grid">${APP_DATA.meta.exams.map(y=>`<div class="card"><h2>${examKey(y)}</h2><p class="small">13 môn • 125 câu</p><button class="btn primary" onclick="chooseSubjectMenu('${examKey(y)}')">📖 CHỌN 13 MÔN</button></div>`).join('')}</div>`}
